    //MSSFUNDS-60: Process Response from Upstream teams
    responseFromUpstream: function(payload) { //story 60
        // Example usage with your HTML content as a string
        try {
            var faMakerGroup = gs.getProperty('x_hsb11_mss_fund_0.FA_Ops_Maker_Group'); // MSSFUNDS-210: Sys ID Of FA Ops Maker Group
            var parsePayload = JSON.parse(payload.toString());
            var getBody = parsePayload.Email_Body;
            var htmlContent = getBody;
            var breakBody = htmlContent.indexOf("Position breaks:");
            var parts = htmlContent.split('Position breaks:');
            var s1 = parts[0];
            var s2 = parts[1];
            var before = this.extractTableData(s1);
            var arr1 = [];
            before.forEach((before, tableIndex) => {
                before.forEach((row, rowIndex) => {
                    arr1.push(row[0] + "-" + row[14] + "-" + row[15]);
                });
            });
            var after = this.extractTableData(s2);
            var arr2 = [];
            after.forEach((after, tableIndex) => {
                after.forEach((row, rowIndex) => {
                    arr2.push(row[0] + "-" + row[17] + "-" + row[18]);
                });

            });
            var arr3 = arr1.concat(arr2);
            for (var i = 1; i < arr3.length; i++) {
                var response = arr3[i];
                var firstdash = response.indexOf('-');
                var secdash = response.indexOf('-', firstdash + 1);
                var thirddash = response.lastIndexOf('-');
                var excid = response.substr(0, firstdash);
                var res = response.substr(firstdash + 1, secdash - firstdash - 1);
                var com = response.substr(thirddash + 1);
                var gr = new GlideRecord('x_hsb11_mss_fund_0_funds_task');
                gr.addQuery('exception_id', excid);
                gr.query();
                while (gr.next()) {
                    if (res.toLowerCase() === 'yes') {
                        gr.state = '201'; //Resolved
                        gr.break_outcome = 'Resolved';
                        gr.update();
                    } else if (res.toLowerCase() === 'no') {
                        gr.state = '202'; // Open - Unresolved
                        gr.break_outcome = 'Unresolved';
                        gr.assignment_group = faMakerGroup; //FA Operations - Maker
                        gr.work_notes = com;
                        gr.update();
                    }
                }
            }
        } catch (e) {
            gs.info("Script Include - MSS_Funds_Utils - Unknown Exception While Receiving and Processing Response Emails from Upstream Teams " + e.message);
        }
    },

