            var finalResponse = getBody.substr(startIndex + 18, endIndex - startIndex - 32); // index adjustment to take only inside part
            //var htmlContent = finalResponse;
            var htmlContent = finalResponse.replaceAll('&nbsp;', ''); //Remove non breaking spaces
            var breakBody = htmlContent.indexOf("Position breaks:");
