    //MSSFUNDS-60: Remove HTML tags
    cleanString: function(str) {
        //Removing HTML tags
        var cleanedStr = str.replace(/<\/?[^>]+(>|$)/g, "");
        //Replace common HTML entities with their corresponding characters
        cleanedStr = cleanedStr.replace(/&amp;/g, '&')
            .replace(/&lt;/g, '<')
            .replace(/&gt;/g, '>')
            .replace(/&quot;/g, '"')
            .replace(/&#39;/g, "'");
        return cleanedStr.trim();
    },

    //MSSFUNDS-60: Get contains from reponse table
    extractTableData: function(htmlContent) {
        // Use a more specific regex to match only the content within <table> tags
        const tableRegex = /<table[\s\S]*?>[\s\S]*?<\/table>/gi;
        var tables = [];
        var match;
        while ((match = tableRegex.exec(htmlContent)) !== null) {
            var tableContent = match[0];
            var rows = [];
            // Match rows within the table
            var rowMatches = tableContent.match(/<tr[\s\S]*?>[\s\S]*?<\/tr>/gi);
            if (rowMatches) {
                rowMatches.forEach(row => {
                    var cells = [];
                    // Match cells within the row, including both td and th tags
                    var cellMatches = row.match(/<(td|th)[\s\S]*?>[\s\S]*?<\/(td|th)>/gi);
                    if (cellMatches) {
                        cellMatches.forEach(cell => {
                            // Clean cell content
                            cells.push(this.cleanString(cell));
                        });
                    }
                    rows.push(cells);
                });
            }
            tables.push(rows);
        }
        return tables;
    },
    //MSSFUNDS-210: Return Task IDs from email body
    emailLogTaskIDs: function(dept, body) {
        try {
            var htmlContent;
            if (dept == 'CORPORATE ACTION') { //Take body part if department = CA
                var startIndex = body.indexOf('<td id="response">');
                var endIndex = body.indexOf('<td id="root">');
                var finalResponse = body.substr(startIndex + 18, endIndex - startIndex - 32); // index adjustment to take only inside part
                //var htmlContent = finalResponse;
                htmlContent = finalResponse.replaceAll('&nbsp;', ''); //Remove non breaking spaces
            } else {
                // For upstream, no cascaded table, so return current body directly
                htmlContent = body;
            }
            var breakBody = htmlContent.indexOf("Position breaks:");
            var parts = htmlContent.split('Position breaks:');
            var s1 = parts[0];
            var s2 = parts[1];
            var before = this.extractTableData(s1);
            var arr1 = [];
            before.forEach((before, tableIndex) => { // Loop on Case breaks table
                before.forEach((row, rowIndex) => {
                    arr1.push(row[0] + "-" + row[14] + "-" + row[15]);
                });
            });
            var after = this.extractTableData(s2);
            var arr2 = [];
            after.forEach((after, tableIndex) => { // Loop on Position breaks table
                after.forEach((row, rowIndex) => {
                    arr2.push(row[0] + "-" + row[17] + "-" + row[18]);
                });
            });
            var excIDArray = []; // array to store task ids
            var arr3 = arr1.concat(arr2); // merge cash and position breaks
            for (var i = 1; i < arr3.length; i++) {
                var response = arr3[i];
                var firstdash = response.indexOf('-');
                var excid = response.substr(0, firstdash);
                var grFundTask = new GlideRecord('x_hsb11_mss_fund_0_funds_task');
                grFundTask.addQuery('exception_id', excid);
                grFundTask.query(); // take breaks and update response
                while (grFundTask.next()) {
                    //Push task numbers into array
                    excIDArray.push(grFundTask.number.toString());
                }
            }
            return excIDArray; // Return Array of Fund Task Numbers
        } catch (e) {
            gs.info("Script Include - MSS_Funds_Utils - Unknown Exception While Returnin Task IDs" + e.message);
        }
    },
    //MSSFUNDS-209: Convert UK to HK using fix timezone
    convertTimeToHK: function(slaTimer) {
        var gdt = new GlideDateTime(slaTimer);
        gdt.addSeconds(28800); //8Hrs - Difference between HK and UK timezone
        var hkTime = gdt.getTime().getByFormat('HH:mm:ss');
        return hkTime;
    },

    type: 'MSS_Funds_Utils'
};
